const training=$('Training Completions').all().map(i=>i.json);
const feedback=$('Feedback Submissions').all().map(i=>i.json);
const scores={};
for(const t of training){
  if(!scores[t.email]) scores[t.email]={name:t.full_name,dept:t.department,email:t.email,total:0,training:0,feedback:0};
  scores[t.email].training+=parseInt(t.training_score||0)*10; // 10pts per training
  scores[t.email].total+=scores[t.email].training;
}
for(const f of feedback){
  if(!scores[f.email]) scores[f.email]={name:f.email,dept:'Unknown',email:f.email,total:0,training:0,feedback:0};
  scores[f.email].feedback+=parseInt(f.feedback_score||0)*5; // 5pts per TP verdict
  scores[f.email].total+=scores[f.email].feedback;
}
const ranked=Object.values(scores).sort((a,b)=>b.total-a.total).slice(0,10);
const medals=['🥇','🥈','🥉','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];
return[{json:{ranked:ranked.map((r,i)=>({...r,rank:i+1,medal:medals[i]||String(i+1)})),top3:ranked.slice(0,3),week_ending:new Date().toISOString().split('T')[0]}}];
